static const char *tname_tbl(uint16_t w) {
    uint16_t base = (w & 0x0800) ? (w & 0xFBFF) : (w & 0xF0FF);   /* strip autopop (tool) / flag bits (OS) */
    for (int i = 0; trapnames[i].w; i++) if (trapnames[i].w == base || trapnames[i].w == w) return trapnames[i].n;
    return "?";
}
